/**
 * Swagger/OpenAPI docs for recurring task routes.
 */

/**
 * @swagger
 * tags:
 *   - name: RecurringTasks
 *     description: Recurring task management endpoints
 */

/**
 * @swagger
 * components:
 *   schemas:
 *     RecurringTask:
 *       type: object
 *       required:
 *         - name
 *         - userId
 *       properties:
 *         _id:
 *           type: string
 *           description: Auto-generated MongoDB ObjectId
 *         name:
 *           type: string
 *           description: Name of the recurring task
 *         description:
 *           type: string
 *           description: Optional description of the recurring task
 *         userId:
 *           type: string
 *           description: User ID who owns this recurring task
 *         createdDate:
 *           type: string
 *           format: date-time
 *         updatedDate:
 *           type: string
 *           format: date-time
 *         isActive:
 *           type: boolean
 *           description: Whether the recurring task is active
 *         taskIds:
 *           type: array
 *           items:
 *             type: string
 *           description: List of task IDs generated by this recurring task
 *       description: |
 *         When a task is completed with `completed.recur = true` and does not have a `recurId`,
 *         a new RecurringTask is created with the completed task's ID in `taskIds`.
 *         The completed task is updated with the new `recurId`.
 *         A new task is then created with the same properties and added to the RecurringTask's `taskIds`.
 *         If a task is completed with `completed.recur = false` and has a `recurId`, the RecurringTask's `isActive` is set to false.
 *       example:
 *         _id: 6628e7b2c1a4e2a1b8c1d2e3
 *         name: Weekly Review
 *         description: Review weekly progress
 *         userId: 69d977b8abda6e6ee0cc1f29
 *         createdDate: 2026-04-24T10:00:00.000Z
 *         updatedDate: 2026-04-24T10:00:00.000Z
 *         isActive: true
 *         taskIds: [6628e7b2c1a4e2a1b8c1d2e4]
 */

